const agents = {
  lume: {name:'Lume',category:'SITES & EXPERIÊNCIA',description:'Uma página com estratégia, identidade e uma ação principal definida.',deliveries:['Título, texto e chamadas para ação','Direção visual e layout para celular e desktop','Implementação e revisão de links e interações'],prompt:'/criar\nQuero uma landing page para [negócio ou produto].\nPúblico: [quem quero alcançar].\nObjetivo principal: [contato, inscrição ou outra ação].\nOferta e diferencial: [o que entrego].\nEstilo e referências: [preferências].\nMateriais disponíveis: [textos, marca e imagens].\nDestino do botão principal: [endereço confirmado].'},
  lucila: {name:'Lucila',category:'MARKETING & PLANEJAMENTO',description:'Marketing, Design Thinking e cronogramas conectados ao seu objetivo.',deliveries:['Público, proposta e hipóteses para testar','Campanha, conteúdo e calendário editorial','Cronograma com entregas, dependências e responsáveis'],prompt:'/integrado\nProjeto: [produto, serviço ou campanha].\nObjetivo: [resultado desejado].\nPúblico: [pessoas que quero alcançar].\nEvidências disponíveis: [dados ou materiais].\nPrazo e capacidade: [tempo e equipe].\nCrie uma proposta testável e um plano de execução. Identifique as premissas que ainda precisam de validação.'},
  joyce: {name:'Joyce',category:'DOCUMENTOS & CPA',description:'Análise documental rastreável e apoio à avaliação institucional.',deliveries:['Inventário dos documentos e cobertura da análise','Achados com referências e classificação de falhas','Minutas de correção e plano de ação para revisão'],prompt:'/auditoria-completa\nObjetivo da análise: [o que preciso conferir].\nContexto institucional: [tipo de instituição e sistema de ensino].\nPeríodo: [datas].\nDocumentos: [forneça os arquivos com acesso autorizado].\nFaça o inventário, informe a cobertura da leitura e identifique inconsistências com referências. Separe fatos, interpretações e recomendações.'},
  jobs: {name:'Mentor Jobs',category:'PRODUTO & FOCO',description:'Persona de IA inspirada em critérios de produto de Steve Jobs, para discutir foco, experiência e execução.',deliveries:['Definição de público, problema e experiência central','Crítica de produto ou pitch com correções práticas','Próxima entrega com escopo e critérios de conclusão'],prompt:'/produto\nMinha ideia: [descreva].\nPúblico e problema: [quem usa e qual dificuldade].\nEstágio atual: [ideia, protótipo ou produto].\nRecursos e restrições: [tempo, equipe e orçamento].\nAjude a definir a experiência central, simplificar o escopo e escolher a próxima entrega verificável.'},
  bezos: {name:'Mentor Bezos',category:'CLIENTE & ESTRATÉGIA',description:'Persona de IA inspirada no raciocínio de gestão de Jeff Bezos, para discutir benefício ao cliente e execução.',deliveries:['Proposta de valor e hipóteses críticas','Experimento com indicadores e critérios de revisão','Fluxo de operação e mecanismos de acompanhamento'],prompt:'/experimento\nProposta de negócio: [descreva].\nCliente e problema: [quem precisa e por quê].\nEvidências atuais: [o que já sabemos].\nRecursos disponíveis: [tempo, equipe e orçamento].\nProponha um teste pequeno para avaliar a hipótese principal, com indicador, forma de coleta e critérios para continuar, ajustar ou parar.'},
  x: {name:'Agente X',category:'ORDENS DE SERVIÇO',description:'Acompanhamento objetivo das ordens de serviço a partir dos registros que você fornece.',deliveries:['Resumo por O.S. com status, prazo e próxima ação','Painel de pendências próprias e de terceiros','Reporte curto para acompanhamento com a liderança'],prompt:'/painel\nVou fornecer meus registros de ordens de serviço.\n[Insira números, assuntos, status, prazos e atualizações disponíveis.]\nOrganize uma tabela com pendências e responsáveis. Preserve os números originais e destaque minhas próximas ações. Use “não informado” onde faltarem dados; não inclua gestão financeira.'}
};
const dialog=document.querySelector('#agent-dialog');
const promptField=document.querySelector('#agent-prompt');
const status=document.querySelector('#copy-status');
document.querySelectorAll('[data-agent]').forEach(button=>button.addEventListener('click',()=>{
  const agent=agents[button.dataset.agent];
  document.querySelector('#dialog-title').textContent=agent.name;
  document.querySelector('#dialog-category').textContent=agent.category;
  document.querySelector('#dialog-description').textContent=agent.description;
  document.querySelector('#dialog-deliveries').replaceChildren(...agent.deliveries.map(text=>{const item=document.createElement('li');item.textContent=text;return item;}));
  promptField.value=agent.prompt;status.textContent='';dialog.showModal();
}));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const bounds=dialog.getBoundingClientRect();if(event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom)dialog.close();}});
document.querySelector('#copy-prompt').addEventListener('click',async()=>{
  try{await navigator.clipboard.writeText(promptField.value);status.textContent='Pedido copiado. Leve para sua conversa com o agente.';}
  catch{promptField.focus();promptField.select();status.textContent='Selecionei o pedido. Use Ctrl+C ou a opção Copiar do seu dispositivo.';}
});
